87	/**
88	 * Edits are allowed inside a fifteen-minute window, or by anyone the role
89	 * matrix already lets update a comment. `can()` decides the second half —
90	 * this service only owns the time window.
91	 */
92	export async function updateComment(
93	  actor: Actor,
94	  input: UpdateCommentInput,
95	): Promise<Comment> {
96	  assertOrgScope(actor, input.orgId);
97	
98	  const comment = requireFound(
99	    await commentRepo.findCommentById(input.orgId, input.commentId),
100	    "Comment",
101	    input.commentId,
102	  );
